function normalizeSearch(value: string) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("pt-BR").trim();
}

function queryTokens(value: string) {
  return normalizeSearch(value.replace(/[0-9.]+/g, " ")).split(/\s+/).filter(token => token.length >= 2);
}

export function getFinancialRubricByCode(value: string | null | undefined) {
  const code = (value ?? "").replace(/\D/g, "");
  return financialRubricCatalog.find(item => item.code === code);
}

export function searchFinancialRubrics(value: string, limit = 30) {
  const raw = value.trim();
  if (!raw) return [];
  const normalized = normalizeSearch(raw);
  const codeQuery = raw.replace(/\D/g, "");
  const tokens = queryTokens(raw);
  const results = financialRubricCatalog.filter(item => {
    const title = normalizeSearch(item.title);
    const codeMatch = codeQuery.length >= 2 && item.code.startsWith(codeQuery);
    const titleMatch = tokens.length > 0 && tokens.every(token => title.includes(token));
    return codeMatch || titleMatch || (codeQuery.length < 2 && title.includes(normalized));
  });
  return [...results].sort((a, b) => {
    const aExact = a.code === codeQuery ? 0 : a.code.startsWith(codeQuery) && codeQuery.length >= 2 ? 1 : 2;
    const bExact = b.code === codeQuery ? 0 : b.code.startsWith(codeQuery) && codeQuery.length >= 2 ? 1 : 2;
    return aExact - bExact || a.code.localeCompare(b.code);
  }).slice(0, limit);
}
